})

describe('handle', () => {
  it('happy path: creates or updates contact with correct request', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url.includes('/contacts/v1/contact/createOrUpdate/email/')
        ? jsonResponse({ vid: 12345, isNew: true }, 201)
        : jsonResponse({ error: 'not found' }, 404),
    )

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_test_session_id: 'cs_test_123',
      customer: { email: 'test@example.com' },
    }

    const config: ConnectorConfig = {
      hubspotAccessToken: 'hubspot-token-abc',
      fetch,
    }

    const result = await handle(payload, config)

    expect(result).toEqual({ hubspotContactId: 12345, isNew: true })
    expect(calls).toHaveLength(1)

    const call = calls[0]
    expect(call.method).toBe('POST')
    expect(call.url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com')
    expect(call.headers.get('authorization')).toBe('Bearer hubspot-token-abc')
    expect(call.headers.get('idempotency-key')).toBe('cs_test_123')
    expect(call.json).toEqual({
      properties: [{ property: 'email', value: 'test@example.com' }],
    })
  })

  it('uses Idempotency-Key header from Stripe session id', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ vid: 999, isNew: false }))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_idempotency_key_123',
      customer: { email: 'idem@example.com' },
    }

    await handle(payload, { hubspotAccessToken: 'token', fetch })

    expect(calls[0].headers.get('idempotency-key')).toBe('cs_idempotency_key_123')
  })

  it('URL-encodes email with special characters', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ vid: 1, isNew: true }))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_1',
      customer: { email: 'user+tag@example.com' },
    }

    await handle(payload, { hubspotAccessToken: 'token', fetch })

    expect(calls[0].url).toBe('https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/user%2Btag%40example.com')
  })

  it('throws on missing id', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      customer: { email: 'test@example.com' },
    } as StripeCheckoutSessionCompletedPayload

    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow(
      'Missing required field: id (Stripe session id)',
    )
  })

