    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      id: 'cs_123',
      customer: {},
    } as StripeCheckoutSessionCompletedPayload

    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow(
      'Missing required field: customer.email',
    )
  })

  it('throws on non-2xx response with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch((req) => jsonResponse({ message: 'Unauthorized' }, 401))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      customer: { email: 'test@example.com' },
    }

    await expect(handle(payload, { hubspotAccessToken: 'bad-token', fetch })).rejects.toThrow(
      'HubSpot API error: 401 Unauthorized for https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com',
    )
    expect(calls).toHaveLength(1)
  })

  it('throws on 500 response', async () => {
    const { fetch } = fakeFetch((req) => jsonResponse({ message: 'Internal Server Error' }, 500))

    const payload: StripeCheckoutSessionCompletedPayload = {
      id: 'cs_123',
      customer: { email: 'test@example.com' },
    }

    await expect(handle(payload, { hubspotAccessToken: 'token', fetch })).rejects.toThrow(
      'HubSpot API error: 500 Internal Server Error for https://api.hubapi.com/contacts/v1/contact/createOrUpdate/email/test%40example.com',
    )
  })
})

